arguments.argument:
if sys_minimap.mouse_check=0 and sys_minimap.mouse_coll_check=0
{
    global.drag_x=mouse_x
    global.drag_y=mouse_y
    click=1
}

if mouse_sie=1 and !mouse_check
{
    for(i=0; i!=vab_unit; i+=1)
    {
        with(vab_unit_id[i])
        {
            if global.player_control=player
            {
                moni_go_waits=0
                attack_waits=1
                go_check=1
                go_x=mouse_x
                go_y=mouse_y
                image_index=round(point_direction(x, y, go_x, go_y)/90)
                
                /*on*/buffer_clear(fnv_sned)
                write_uint(fnv_sned, on)
                write_uint(fnv_sned, go_x)
                write_uint(fnv_sned, go_y)
                write_uint(fnv_sned, x)
                write_uint(fnv_sned, y)
                fn_message_send(global.socket, send_other, 22)
            }
        }
    }
    mouse_sie=0
    instance_create(mouse_x, mouse_y, obj_etc)
}

if bil_ok=1
{
    sprite_index=global.unit_id_spr[bil_id, 0]
    if !place_meeting(mouse_x, mouse_y, sys_inter) and !place_meeting(mouse_x, mouse_y, obj_moni) and !place_meeting(mouse_x, mouse_y, obj_unit) and !place_meeting(mouse_x, mouse_y, obj_bil) and !sk_in_fog(mouse_x, mouse_y, 1)
    {
        bil_ok=0
        /*on*/buffer_clear(fnv_sned)
        write_uint(fnv_sned, mouse_x)
        write_uint(fnv_sned, mouse_y)
        write_uint(fnv_sned, bil_id)
        write_uint(fnv_sned, global.player_control)
        fn_message_send(global.socket, send_server, 14)
    }
}
